(function(){'use strict';
document.documentElement.classList.add('perspective-enabled');document.body.classList.add('forwarders-view');
const compactCss=document.createElement('link');compactCss.rel='stylesheet';compactCss.href='perspectives.css';document.head.appendChild(compactCss);
new ResizeObserver(()=>document.documentElement.style.setProperty('--perspective-header-height',document.querySelector('.site-header').getBoundingClientRect().height+'px')).observe(document.querySelector('.site-header'));
const api=window.VersionCompassForwarders,d=window.VersionCompassForwarderData,parsed=api.read(location.search),state=parsed.state;let linkErrors=parsed.errors,model;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const themed=u=>window.VersionCompassTheme?.href(u)||u;
const names={uf:'Universal Forwarder',hf:'Heavy Forwarder',cmp:'CMP',cloud:'Splunk Cloud commercial','fr-m':'FR-M','fr-h':'FR-H',unspecified:'Not specified',x86_64:'x86-64',arm64:'ARM64',aws:'AWS',azure:'Azure',gcp:'Google Cloud',direct:'Direct to receiver',intermediate:'Via intermediate forwarder',edge:'Via Edge Processor',other:'Other / not listed'};
const fieldNames={type:'Forwarder type',from:'Current release line',to:'Target release line',destination:'Destination',receiver:'Receiver release line',os:'Forwarder OS (exact release)',arch:'Forwarder architecture',provider:'Destination provider',topology:'Forwarding topology'};
const cite=k=>{const s=d.sources[k];return s?'<a href="'+esc(s.url)+'">'+esc(s.title)+'</a> · Verified '+esc(s.reviewed)+' · '+esc(s.section):'';};
const card=c=>'<article class="forwarder-record"><h3>'+esc(c.title)+' <span class="source-badge">'+esc(api.labels[c.status])+'</span></h3><p>'+esc(c.detail)+'</p><p class="guidance-note">'+cite(c.source)+'</p></article>';
const technical=t=>'<article class="forwarder-record"><h3>'+esc(t.component)+' · '+esc(t.release||'')+'</h3><p><strong>'+esc(t.changeType)+' · '+esc(t.actionLevel)+'</strong></p><p>'+esc(t.from)+' → '+esc(t.to)+'</p><p>'+esc(t.implication)+'</p><p><strong>Action:</strong> '+esc(t.action)+'</p><a href="'+esc(t.source)+'">Scoped official evidence</a></article>';
const products=document.querySelector('.product-switcher').outerHTML;
document.querySelector('main').innerHTML='<section class="hero"><div class="eyebrow">FORWARDER PLANNING</div><h1>Splunk Forwarders</h1><p class="dek">Plan collection and forwarding upgrades for your receiving environment.</p><div class="selector-card">'+products+'<div class="forwarder-controls">'+Object.keys(fieldNames).map(k=>'<label>'+esc(fieldNames[k])+'<select data-forwarder="'+k+'">'+api.options[k].map(v=>'<option value="'+esc(v)+'">'+esc(names[v]||v)+'</option>').join('')+'</select></label>').join('')+'<label>Destination region code<input data-forwarder="region" maxlength="50" placeholder="us-east-1" aria-describedby="forwarder-scope-note"></label></div><p id="forwarder-scope-note" class="guidance-note">CMP = customer-managed platform: Splunk Enterprise on premises or in your cloud. Region codes qualify features; a supplied code does not establish hosting or authorization. For an intermediate chain, evaluate each hop separately.</p></div><div class="report-actions"><button id="copy-link" type="button">Copy comparison link</button><button id="print-report" type="button">Print / PDF</button><span id="share-status" role="status"></span></div></section><div id="forwarder-warnings" role="alert"></div><div id="results" tabindex="-1"></div><div id="release-report"></div>';
document.querySelectorAll('input[name="product"]').forEach(el=>{el.checked=el.value==='forwarders';el.addEventListener('change',()=>{location.href=themed('?product='+el.value);});});
function availability(c){return '<div class="forwarder-availability">'+['cloud','cmp','fr-m','fr-h'].map(destination=>{const r=api.renewal({...state,destination});return '<details><summary>'+esc(names[destination])+' · '+esc(api.labels[r.status])+'</summary><p>'+esc(r.detail)+'</p><p>'+cite(r.source)+'</p></details>';}).join('')+'</div>';}
function reportBody(m){
 const scope=Object.keys(api.defaults).map(k=>(fieldNames[k]||'Region')+': '+(names[state[k]]||state[k])).join(' · ');
 return '<section class="section" id="route-takeaway"><h2>This route at a glance</h2><p>'+esc(scope)+'</p><p class="decision-compact"><a href="#breaking-title">'+m.risks.length+' potential blockers</a> · <a href="#readiness-title">'+m.requiredChecks.length+' required checks</a> · '+m.claims.filter(c=>c.status==='not_established').length+' evidence questions</p><details class="decision-details"><summary>Expand details</summary><p>'+esc(m.coverage)+'</p><p>'+esc(state.type==='hf'?'Heavy Forwarder uses Splunk Enterprise release evidence, limited here to forwarding, security, service identity and app/runtime implications.':'Universal Forwarder uses its own upgrade prerequisites; Enterprise application-runtime changes are not assigned to UF.')+'</p><p>These counts are a planning inventory, not a readiness score.</p></details></section>'+
 '<section class="section"><h2 id="path-title">Upgrade path and receiver</h2>'+m.claims.map(card).join('')+'<details><summary>Evidence for each upgrade step</summary>'+m.steps.map(s=>'<p>'+esc(s.from+' → '+s.to)+' · '+cite(s.source)+'</p>').join('')+'<p>The shortest recorded supported route is shown. Other supported intermediate routes may exist; review the linked table.</p></details></section>'+
 '<section class="section"><h2 id="value-title">Feature availability at the target</h2><p>These capabilities may already exist in the current release. Eligibility is separate from a newly introduced feature.</p>'+m.features.map(c=>card(c)+availability(c)).join('')+'</section>'+
 '<section class="section"><details class="technical-panel" id="technical-panel"><summary><span id="technical-title">Requirements &amp; dependencies</span></summary><h3>Target requirements</h3>'+card(m.os)+'<p>Target runtime history below identifies successive bundled-runtime changes through the target. Later entries supersede earlier defaults. App-owned runtimes retain the app vendor’s requirements; no premium-app patch pairing is inferred.</p>'+m.targetRuntime.map(technical).join('')+(state.type==='uf'?'<p>No bundled Python or premium-app compatibility claim is established here for UF. Check scripted-input and add-on runtime requirements individually.</p>':'')+'<h3>Changes along your route</h3>'+ (m.technical.length?m.technical.map(technical).join(''):'<p>No additional component transition is curated for this interval. This is not evidence of no change; review each intermediate release and the issue directories below.</p>')+'</details></section>'+
 '<section class="section"><h2 id="breaking-title">Known issues and patch warnings</h2>'+m.risks.map(card).join('')+'<p>'+cite('known')+'</p><p>'+cite('fixed')+'</p><p>These directories point to the Universal Forwarder sections of the Enterprise issue lists. This report does not claim a complete issue inventory for every patch.</p><h3>Security fixes</h3>'+card(m.security)+'<p>'+cite('advisories')+'</p></section>'+
 '<section class="section"><h2 id="readiness-title">Required checks</h2><ol>'+m.requiredChecks.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol><p>'+cite(state.type==='hf'?'enterprise':'upgrade104')+'</p></section>'+
 '<section class="section"><h2 id="source-title">Evidence and coverage</h2><p>'+esc(m.coverage)+'</p><p>Verification dates apply to the named source sections only. Offering authorization never establishes individual feature availability. FR-M and FR-H are independent.</p></section>';
}
function render(){
 model=api.assess(state);const errors=[...linkErrors,...model.errors];document.getElementById('forwarder-warnings').innerHTML=errors.length?'<p>'+errors.map(esc).join('<br>')+'</p><button type="button" id="confirm-forwarder">Use the displayed selections</button>':'';
 document.getElementById('copy-link').disabled=!!errors.length;document.getElementById('print-report').disabled=!!errors.length;
 document.getElementById('results').hidden=!!errors.length;if(errors.length){document.getElementById('confirm-forwarder').onclick=()=>{linkErrors=[];render();};return;}
 const openIds=[...document.querySelectorAll('#results details[open]')].map(e=>e.id||e.querySelector('summary')?.textContent);
 document.getElementById('results').innerHTML=reportBody(model);document.querySelectorAll('#results details').forEach(e=>{e.open=openIds.includes(e.id||e.querySelector('summary')?.textContent);});
 document.title='Version Compass | '+names[state.type]+' '+state.from+' → '+state.to;
 history.replaceState(null,'',themed(api.url(state)));
}
document.querySelectorAll('[data-forwarder]').forEach(el=>{el.value=state[el.dataset.forwarder];el.addEventListener('change',()=>{state[el.dataset.forwarder]=el.value.trim()||'unspecified';linkErrors=[];render();});});
window.addEventListener('popstate',()=>{const next=api.read(location.search);Object.assign(state,next.state);linkErrors=next.errors;document.querySelectorAll('[data-forwarder]').forEach(e=>e.value=state[e.dataset.forwarder]);render();});
document.getElementById('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);document.getElementById('share-status').textContent='Comparison link copied.';}catch{document.getElementById('share-status').textContent='Copy this link: '+location.href;}};
window.VersionCompassBuildSnapshot=()=>{if(linkErrors.length||model.errors.length)throw Error('Resolve selection warnings first.');return window.VersionCompassReports.decorate('<h1>'+esc(document.title)+'</h1><p>Full selected forwarder report, including target requirements, route changes, warnings, qualifications and citations.</p>'+reportBody(model));};
function prepare(){if(linkErrors.length||model.errors.length)return;document.getElementById('release-report').innerHTML=window.VersionCompassBuildSnapshot();document.getElementById('release-report').querySelectorAll('details').forEach(e=>e.open=true);document.documentElement.classList.add('printing-report');}
window.addEventListener('beforeprint',prepare);window.addEventListener('afterprint',()=>document.documentElement.classList.remove('printing-report'));
document.getElementById('print-report').onclick=()=>{prepare();window.print();};
render();
}());
/* Read-only page tool shares the exact report model. */
(function(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const api=window.VersionCompassForwarders;try{Promise.resolve(context.registerTool({name:'compare_forwarder_routes',title:'Compare forwarder routes',description:'Read evidence-backed forwarder upgrade, receiver, environment and requirements assessments. Does not change selections or certify readiness.',inputSchema:{type:'object',additionalProperties:false,required:['routes'],properties:{routes:{type:'array',minItems:1,maxItems:8,items:{type:'object',additionalProperties:false,properties:Object.fromEntries(Object.keys(api.defaults).map(k=>[k,k==='region'?{type:'string',pattern:'^[a-z0-9-]{1,50}$'}:{type:'string',enum:api.options[k]}]))}}}},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||!Array.isArray(input.routes)||input.routes.length<1||input.routes.length>8||Object.keys(input).some(k=>k!=='routes'))throw Error('Supply 1–8 routes.');return {revision:window.VersionCompassRevision,reports:input.routes.map(r=>{if(!r||typeof r!=='object'||Object.keys(r).some(k=>!(k in api.defaults)))throw Error('Invalid forwarder fields');return api.assess({...api.defaults,...r});}),sources:window.VersionCompassForwarderData.sources};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}());
